/// Contracts: wire types generated by wehoop-api `pnpm gen:swift` (GameChange, the
/// LiveEvent bodies, Pulse, Snapshot, the `/changes` page, `/v1/players/:id`, and the
/// `v_schedule` / `v_boxscore` / `v_standings` / `v_player_seasons` rows). Codable and
/// `Sendable`, no dependencies. Generated files are never edited by hand; CI fails when
/// the generated output differs from what is committed (from S1).
///
/// S0 placeholder: the generator lands in S1 (backend B1).

/// Where the generated contract files come from.
public enum ContractsSource {
    /// The backend command that emits this module's files.
    public static let generator = "pnpm gen:swift"
}
